// Config plugin for the local yt-dlp module. android/ is generated by prebuild, so the
// packaging settings youtubedl-android needs are applied here instead of by hand.
// - python/qjs ship as .so files that must be extracted to nativeLibraryDir at install time
//   (extractNativeLibs + legacy jniLibs packaging, which AGP otherwise overrides).
// - only ARM ABIs are packaged.
const { withAndroidManifest, withAppBuildGradle, withGradleProperties } = require('expo/config-plugins');

const ABIS = ['arm64-v8a', 'armeabi-v7a'];

function setProperty(props, key, value) {
  const existing = props.find((p) => p.type === 'property' && p.key === key);
  if (existing) existing.value = value;
  else props.push({ type: 'property', key, value });
}

module.exports = function withYtdlp(config) {
  config = withAndroidManifest(config, (c) => {
    const app = c.modResults.manifest.application?.[0];
    if (app) app.$['android:extractNativeLibs'] = 'true';
    return c;
  });

  config = withGradleProperties(config, (c) => {
    setProperty(c.modResults, 'expo.useLegacyPackaging', 'true');
    setProperty(c.modResults, 'reactNativeArchitectures', ABIS.join(','));
    return c;
  });

  config = withAppBuildGradle(config, (c) => {
    const marker = '// ytdlp-abi-filters';
    if (!c.modResults.contents.includes(marker)) {
      const filters = ABIS.map((a) => `"${a}"`).join(', ');
      c.modResults.contents = c.modResults.contents.replace(
        /defaultConfig\s*\{/,
        (m) => `${m}\n        ndk { abiFilters ${filters} } ${marker}`,
      );
    }
    return c;
  });

  return config;
};
